sp() { awk '
{
  if ($0 ~ /^[[:space:]]*```/) { infence = !infence; next }
  if (infence) next
  stripped = $0
  sub(/^[[:space:]]*[#>*|`_-]*[[:space:]]*/, "", stripped)
  if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:/) {
    found = 1
    if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:[[:space:]]*\*{0,2}`{0,1}[[:space:]]*[Pp]iena[[:space:]]*`{0,1}\*{0,2}[[:space:]]*$/) {
      ok = 1
    } else if (stripped ~ /^[Mm]odalit[aà][[:space:]]*:[[:space:]]*\*{0,2}`{0,1}[[:space:]]*[Rr]idotta.*[Mm]issing:[[:space:]]*(rule-librar[a-z]*|glossary|graph-verif[a-z]*)([,[:space:]]+(rule-librar[a-z]*|glossary|graph-verif[a-z]*))*[[:space:]]*$/) {
      ok = 1
    } else {
      bad = 1
    }
  }
}
END { if (found != 1 || bad == 1) exit 1; exit 0 }
' "$1"; }; test -z "$ARTIFACT" || sp "$ARTIFACT" || exit 1
